%[text] This is my Matlab file for the project in the course Transformmetoder
%[text] Constants:
r = 5000 %[output:7e9c2afd]
c = 20*10^-9 %[output:76a8a157]
l = 50*10^-3 %[output:359d626c]

t = linspace(0,0.002,2000);
%[text] Circuit values
omega_0 = 1/sqrt(l*c) %[output:3236a84c]
alpha = 1/(2*r*c) %[output:531abf5d]
omega_d = sqrt(omega_0^2 - alpha^2) %[output:6f6ee49d]
%[text] 
u_ut = 1 - (2*alpha/omega_d) .* exp(-alpha*t) .* sin(omega_d * t) ;
%[text] Transferfunction
s = tf("s");

H = (s^2 +omega_0^2)/(s^2 + omega_0^2 + 2*alpha * s) %[output:7ee2c6ef]

[u_num, t_num] = step(H, t);
%[text] Plots
plot(t, u_ut, "b.", LineWidth=1) %[output:63c72acf]
hold on %[output:63c72acf]
plot(t_num, u_num, "g--", LineWidth = 1) %[output:63c72acf]
hold off  %[output:63c72acf]

legend("Analytisk analys", "Numerisk analys") %[output:63c72acf]

%[text] Bode diagram
w = logspace(3.5, 5.5, 2000);
bode(H, w) %[output:1046a134]
grid on; %[output:1046a134]
%[text] By visual inspection I can see that it is an bandpass filter. The filters lets both low and high frequencies pass through but not frequencies around 3.16 \* 10^4.
%[text] 
%[text] For the square wave input I use the fourier series from The BETA mathematics handbook for engineers. 
%[text] 
%[text] $f(t) = \\frac{2h}{\\pi} \\sum\_{n=1}^{\\infty} \\frac{1 - \\cos(n\\pi\\alpha)}{n} \\sin\\left(\\frac{n\\pi t}{L}\\right)$
%[text] alpha is 0.5
%[text] h is 0.5
%[text] and I add a DC with 0.5 voltage to get up the bottom voltage to zero.
%[text] for every even n we get zero because 1 - 1 = 0
%[text] $x(t) = \\frac{1}{2} + \\frac{2}{\\pi} \\sum\_{k=1,3,5,\\dots}^{\\infty} \\frac{1}{k} \\sin\\left(\\frac{k\\pi t}{L}\\right)$
%[text] 
T0 = 0.2e-3;

x_str = strings(5, 1);
freq = zeros(5, 1);
gain = zeros(5, 1);
phase = zeros(5, 1);
y_str = strings(5, 1);


